                  <div className="bg-amber-50 border border-amber-200 text-amber-800 rounded-xl p-4 space-y-2">
                    <h4 className="font-bold flex items-center gap-1 text-[11px]">
                      <AlertCircle size={14} /> Linked records prevent deletion
                    </h4>
                    <p className="text-[11px] leading-normal text-amber-900">
                      Remove or reassign these linked records before deleting this institution:
                    </p>
                    <ul className="list-disc pl-4 text-[10px] space-y-1 font-semibold text-amber-950">
                      <li>{relationCounts.cohorts} Group(s)</li>
                      <li>{relationCounts.programs} Academic Program(s)</li>
                      <li>{relationCounts.users} User(s)</li>
                    </ul>
                  </div>
                )}

                <div className="space-y-2">
                  <label className="block font-semibold text-[#C2C6D1]">
                    Type the name of the institution to confirm (case-sensitive):
                    <span className="block text-[#EDEFF5] font-bold mt-1 select-all">{instToDelete.name}</span>
                  </label>
                  <input
                    type="text"
                    value={deleteConfirmName}
                    onChange={(e) => setDeleteConfirmName(e.target.value)}
                    placeholder="Type the exact name here"
                    className="w-full bg-[#131418] border border-red-200 rounded-lg px-3 py-2 text-xs focus:outline-none focus:border-red-500 shadow-sm text-red-700 font-semibold"
                  />
                </div>
              </div>

              <div className="p-4 border-t border-[#23252C] bg-[#16171D] flex flex-wrap items-center justify-end gap-2">
                <button
                  onClick={() => setIsDeleteModalOpen(false)}
                  className="bg-[#131418] border border-[#23252C] text-[#EDEFF5] hover:bg-[#1A1C22] font-bold py-2 px-4 rounded-xl transition-all cursor-pointer"
                >
                  Cancel
                </button>
                <button
                  onClick={handleConfirmDelete}
                  disabled={deleteButtonDisabled}
                  className="bg-red-600 hover:bg-red-700 text-white font-bold py-2 px-4 rounded-xl transition-all disabled:opacity-30 cursor-pointer"
                >
                  {loading ? "Deleting..." : "Permanently Delete"}
                </button>
              </div>
            </div>
          </div>
        );
      })()}

      {(() => {
        if (!isUserDeleteModalOpen || !userToDelete) return null;

        const deleteButtonDisabled = userDeleteConfirmEmail.trim() !== userToDelete.email || userDeleteLoading;

        return (
          <div className="fixed inset-0 z-50 flex items-center justify-center p-4 overflow-hidden text-xs">
            <div className="absolute inset-0 bg-black/40 backdrop-blur-sm transition-opacity" onClick={() => setIsUserDeleteModalOpen(false)} />
            <div className="bg-[#131418] rounded-2xl border border-[#23252C] max-w-md w-full overflow-hidden shadow-2xl z-10 transform transition-all duration-300" style={{ animation: "modal-fade 0.2s ease-out both" }}>
              <div className="p-6 border-b border-[#23252C] bg-red-50 text-red-800 flex items-center gap-2">
                <AlertCircle size={20} className="shrink-0" />
                <h3 className="font-bold text-sm">CRITICAL: Confirm User Deletion</h3>
              </div>

              <div className="p-6 space-y-4">
                <p className="leading-relaxed text-[#EDEFF5]">
                  You are about to permanently delete the user <strong>{userToDelete.name}</strong> ({userToDelete.email}).
                  This will completely remove them and all their invitations, roles, and records from our system. This action is irreversible.
                </p>

                <div className="space-y-2">
                  <label className="block font-semibold text-[#C2C6D1]">
                    Type the email address of the user to confirm:
                    <span className="block text-[#EDEFF5] font-bold mt-1 select-all">{userToDelete.email}</span>
                  </label>
                  <input
                    type="text"
                    value={userDeleteConfirmEmail}
                    onChange={(e) => setUserDeleteConfirmEmail(e.target.value)}
                    placeholder="Type user's exact email here"
                    className="w-full bg-[#131418] border border-red-200 rounded-lg px-3 py-2 text-xs focus:outline-none focus:border-red-500 shadow-sm text-red-700 font-semibold"
                  />
                </div>
              </div>

              <div className="p-4 border-t border-[#23252C] bg-[#16171D] flex flex-wrap items-center justify-end gap-2">
                <button
                  onClick={() => setIsUserDeleteModalOpen(false)}
                  className="bg-[#131418] border border-[#23252C] text-[#EDEFF5] hover:bg-[#1A1C22] font-bold py-2 px-4 rounded-xl transition-all cursor-pointer"
                >
                  Cancel
                </button>
                <button
                  onClick={handleConfirmUserDelete}
                  disabled={deleteButtonDisabled}
                  className="bg-red-600 hover:bg-red-700 text-white font-bold py-2 px-4 rounded-xl transition-all disabled:opacity-30 cursor-pointer"
                >
                  {userDeleteLoading ? "Deleting..." : "Permanently Delete"}
                </button>
              </div>
            </div>
          </div>
        );
      })()}

      </AppShell>
    </>
  );
}

"use client";
import type { ProjectSubmission, QuizAttempt } from "@/types/campus";

import type { Cohort, Enrollment, Activity, ChallengeSubmission, CohortReport } from "@/types/campus";
import React, { useMemo, useState } from "react";
import { BarChart3, Trophy, AlertTriangle, Target, Award, Users } from "lucide-react";
import { HBarChart, VBarChart, DonutChart, StatTile, HBarDatum, VBarDatum, DonutDatum } from "@/components/analytics-charts";
import { CustomSelect } from "@/components/custom-select";

interface AnalyticsTabProps {
  cohorts: Cohort[];
  enrollments: Enrollment[];
  activities: Activity[];
  quizAttempts: QuizAttempt[];
  projectSubmissions: ProjectSubmission[];
  challengeSubmissions: ChallengeSubmission[];
  cohortReports: Record<string, CohortReport>;
}

const SCORE_BUCKETS = [
  { id: "0-40", label: "0-40%", min: 0, max: 40, color: "var(--error)" },
  { id: "40-60", label: "40-60%", min: 40, max: 60, color: "var(--warning)" },
  { id: "60-80", label: "60-80%", min: 60, max: 80, color: "var(--accent)" },
  { id: "80-100", label: "80-100%", min: 80, max: 101, color: "var(--success)" },
];

export default function AnalyticsTab({
  cohorts,
  enrollments,
  activities,
  quizAttempts,
  projectSubmissions,
  challengeSubmissions,
  cohortReports,
}: AnalyticsTabProps) {
  const [selectedCohortFilter, setSelectedCohortFilter] = useState<string>("all");

  const scopedEnrollments = useMemo(
    () => (selectedCohortFilter === "all" ? enrollments : enrollments.filter((e) => e.cohort_id === selectedCohortFilter)),
    [enrollments, selectedCohortFilter]
  );

  // One person may have enrollments in several programs. Give each person one
  // ranking row and equal weight, averaging their cohort progress first.
  const scopedStudents = useMemo(() => {
    type StudentRow = Enrollment;
    const students = new Map<string, { row: StudentRow; progress: number; count: number }>();
    for (const enrollment of scopedEnrollments) {
      const entry = students.get(enrollment.user_id) || { row: enrollment, progress: 0, count: 0 };
      entry.progress += enrollment.progress_percentage || 0;
      entry.count += 1;
      students.set(enrollment.user_id, entry);
    }
    return [...students.values()].map(entry => ({ ...entry.row, progress_percentage: entry.progress / entry.count }));
  }, [scopedEnrollments]);

  const scopedStudentIds = useMemo(
    () => new Set(scopedEnrollments.map((e) => e.user_id)),
    [scopedEnrollments]
  );

  const scopedQuizAttempts = useMemo(
    () => quizAttempts.filter((a) => scopedStudentIds.has(a.student_id)),
    [quizAttempts, scopedStudentIds]
  );
  const scopedProjectSubs = useMemo(
    () => projectSubmissions.filter((s) => scopedStudentIds.has(s.student_id)),
    [projectSubmissions, scopedStudentIds]
  );
  const scopedChallengeSubs = useMemo(
    () => challengeSubmissions.filter((s) => scopedStudentIds.has(s.student_id)),
    [challengeSubmissions, scopedStudentIds]
  );

  const quizzes = activities.filter((a) => a.activity_type_code === "quiz");
  const projects = activities.filter((a) => a.activity_type_code === "project");
  const challenges = activities.filter((a) => a.activity_type_code === "programming");

  // KPIs -----------------------------------------------------------------
  const totalStudents = scopedStudents.length;

  const avgProgress = totalStudents > 0
    ? Math.round(scopedStudents.reduce((acc, e) => acc + (e.progress_percentage || 0), 0) / totalStudents)
    : 0;

  const passedAttempts = scopedQuizAttempts.filter((a) => a.passed).length;
  const quizPassRate = scopedQuizAttempts.length > 0 ? Math.round((passedAttempts / scopedQuizAttempts.length) * 100) : 0;

  const avgQuizScorePct = useMemo(() => {
    const scored = scopedQuizAttempts.filter((a) => a.max_score);
    if (scored.length === 0) return 0;
    const sum = scored.reduce((acc, a) => acc + (a.score / a.max_score) * 100, 0);
    return Math.round(sum / scored.length);
  }, [scopedQuizAttempts]);

  const approvedProjects = scopedProjectSubs.filter((s) => s.review?.review_status === "approved").length;
  const projectApprovalRate = scopedProjectSubs.length > 0 ? Math.round((approvedProjects / scopedProjectSubs.length) * 100) : 0;

  const acceptedChallenges = scopedChallengeSubs.filter((s) => s.submission_status_code === "accepted").length;
  const challengeAcceptRate = scopedChallengeSubs.length > 0 ? Math.round((acceptedChallenges / scopedChallengeSubs.length) * 100) : 0;

  const forfeitedAttempts = scopedQuizAttempts.filter((a) => a.forfeited).length;

  // Cohort performance -----------------------------------------------------
  const cohortPerformance: HBarDatum[] = useMemo(() => {
    return cohorts
      .filter((c) => selectedCohortFilter === "all" || c.id === selectedCohortFilter)
      .map((c) => {
        const cEnrollments = enrollments.filter((e) => e.cohort_id === c.id);
        const avg = cEnrollments.length > 0
          ? Math.round(cEnrollments.reduce((acc, e) => acc + (e.progress_percentage || 0), 0) / cEnrollments.length)
          : 0;
        return {
          id: c.id,
          label: c.name,
          sublabel: `${cEnrollments.length} students`,
          value: avg,
          color: avg >= 70 ? "var(--success)" : avg >= 40 ? "var(--warning)" : "var(--error)",
        };
      })
      .sort((a, b) => b.value - a.value);
  }, [cohorts, enrollments, selectedCohortFilter]);

  // Quiz score distribution -------------------------------------------------
  const scoreDistribution: VBarDatum[] = useMemo(() => {
    return SCORE_BUCKETS.map((bucket) => {
      const count = scopedQuizAttempts.filter((a) => {
        if (!a.max_score) return false;
        const pct = (a.score / a.max_score) * 100;
        return pct >= bucket.min && pct < bucket.max;
      }).length;
      return { id: bucket.id, label: bucket.label, value: count, color: bucket.color };
    });
  }, [scopedQuizAttempts]);

  // Pass / Fail / Not attempted donut ---------------------------------------
  const quizStatusDonut: DonutDatum[] = useMemo(() => {
    const totalPossible = totalStudents * quizzes.length;
    const attempted = scopedQuizAttempts.length;
    const notAttempted = Math.max(0, totalPossible - attempted);
    const failed = attempted - passedAttempts;
    return [
      { id: "passed", label: "Passed", value: passedAttempts, color: "var(--success)" },
      { id: "failed", label: "Failed", value: Math.max(0, failed), color: "var(--error)" },
      { id: "not_attempted", label: "Not Attempted", value: notAttempted, color: "#A6ACBB" },
    ];
  }, [scopedQuizAttempts, passedAttempts, totalStudents, quizzes.length]);

  // Engagement across activity types ----------------------------------------
  const engagementChart: HBarDatum[] = useMemo(() => {
    const quizEligible = totalStudents * quizzes.length;
    const projectEligible = totalStudents * projects.length;
    const challengeEligible = totalStudents * challenges.length;
    return [
      {
        id: "quizzes",
        label: "Quiz Engagement",
        sublabel: `${scopedQuizAttempts.length}/${quizEligible}`,
        value: quizEligible > 0 ? Math.round((scopedQuizAttempts.length / quizEligible) * 100) : 0,
        color: "var(--primary)",
      },
      {
        id: "projects",
        label: "Project Submissions",
        sublabel: `${scopedProjectSubs.length}/${projectEligible}`,
        value: projectEligible > 0 ? Math.round((scopedProjectSubs.length / projectEligible) * 100) : 0,
        color: "var(--warning)",
      },
      {
        id: "challenges",
        label: "Coding Challenge Runs",
        sublabel: `${scopedChallengeSubs.length}/${challengeEligible}`,
        value: challengeEligible > 0 ? Math.round((scopedChallengeSubs.length / challengeEligible) * 100) : 0,
        color: "var(--accent)",
      },
    ];
  }, [totalStudents, quizzes.length, projects.length, challenges.length, scopedQuizAttempts, scopedProjectSubs, scopedChallengeSubs]);

  // Per-student composite ranking -------------------------------------------
  const studentRankings = useMemo(() => {
    return scopedStudents
      .map((enr) => {
        const sid = enr.user_id;
        const sQuiz = scopedQuizAttempts.filter((a) => a.student_id === sid);
        const quizAvg = sQuiz.length > 0
          ? sQuiz.reduce((acc, a) => acc + (a.max_score ? (a.score / a.max_score) * 100 : 0), 0) / sQuiz.length
          : null;
        const progress = enr.progress_percentage || 0;
        const composite = quizAvg !== null ? Math.round((progress + quizAvg) / 2) : progress;
        return {
          id: enr.user_id,
          name: enr.student?.full_name || enr.student?.email || "Enrolled Student",
          progress,
          quizAvg: quizAvg !== null ? Math.round(quizAvg) : null,
          composite,
        };
      })
      .sort((a, b) => b.composite - a.composite);
  }, [scopedStudents, scopedQuizAttempts]);

  const topPerformers = studentRankings.slice(0, 5);
  const needsAttention = [...studentRankings].reverse().slice(0, 5).filter((s) => s.composite < 70);

  return (
    <div className="space-y-6 animate-fadeIn">
      {/* Cohort filter */}
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-3">
        <div>
          <h3 className="text-xs font-bold uppercase tracking-wider text-[#C2C6D1] flex items-center gap-1.5">
            <BarChart3 size={14} className="text-[#6E79F4]" /> Performance Analytics
          </h3>
          <p className="text-[11px] text-[#C2C6D1] mt-0.5">Deep-dive metrics for this campus only.</p>
        </div>
        <CustomSelect
          className="w-full sm:w-60"
          required
          value={selectedCohortFilter}
          onChange={(v) => setSelectedCohortFilter(v || "all")}
          options={[
            { id: "all", name: "All Cohorts" },
            ...cohorts.map((c) => ({ id: c.id, name: c.name, code: c.code })),
          ]}
        />
      </div>

      {/* KPI tiles */}
      <div className="grid grid-cols-2 lg:grid-cols-3 xl:grid-cols-6 gap-3 sm:gap-4">
        <StatTile label="Students" value={totalStudents} color="var(--primary)" sublabel="In scope" />
        <StatTile label="Avg Progress" value={`${avgProgress}%`} color="var(--primary)" progressPct={avgProgress} />
        <StatTile label="Quiz Pass Rate" value={`${quizPassRate}%`} color="var(--success)" progressPct={quizPassRate} />
        <StatTile label="Avg Quiz Score" value={`${avgQuizScorePct}%`} color="var(--accent)" progressPct={avgQuizScorePct} />
        <StatTile label="Project Approval" value={`${projectApprovalRate}%`} color="var(--warning)" progressPct={projectApprovalRate} />
        <StatTile label="Challenge Accept" value={`${challengeAcceptRate}%`} color="var(--accent)" progressPct={challengeAcceptRate} />
      </div>

      {forfeitedAttempts > 0 && (
        <div className="flex items-center gap-2 bg-[#F0555D]/5 border border-[#F0555D]/15 rounded-xl px-4 py-2.5 text-[11px] text-[#F0555D] font-semibold">
          <AlertTriangle size={14} /> {forfeitedAttempts} quiz attempt{forfeitedAttempts !== 1 ? "s" : ""} forfeited (strict-mode violations) in this scope.
        </div>
      )}

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-4 sm:gap-6">
        {/* Cohort performance */}
        <div className="bg-[#131418] border border-[#23252C] rounded-2xl p-5 shadow-sm space-y-4">
          <h4 className="text-xs font-bold text-[#EDEFF5] flex items-center gap-1.5 pb-3 border-b border-[#23252C]">
            <Users size={14} className="text-[#6E79F4]" /> Average Progress by Cohort
          </h4>
          <HBarChart data={cohortPerformance} emptyLabel="No cohorts to compare yet." />
        </div>

        {/* Quiz status donut */}
        <div className="bg-[#131418] border border-[#23252C] rounded-2xl p-5 shadow-sm space-y-4">
          <h4 className="text-xs font-bold text-[#EDEFF5] flex items-center gap-1.5 pb-3 border-b border-[#23252C]">
            <Target size={14} className="text-[#6E79F4]" /> Quiz Outcomes
          </h4>
          {quizzes.length === 0 ? (
            <div className="text-center py-8 border border-dashed border-[#23252C] rounded-xl text-xs text-[#C2C6D1]">No quizzes published yet.</div>
          ) : (
            <DonutChart data={quizStatusDonut} centerLabel="Total Slots" />
          )}
        </div>

        {/* Score distribution */}
        <div className="bg-[#131418] border border-[#23252C] rounded-2xl p-5 shadow-sm space-y-4">
          <h4 className="text-xs font-bold text-[#EDEFF5] flex items-center gap-1.5 pb-3 border-b border-[#23252C]">
            <BarChart3 size={14} className="text-[#6E79F4]" /> Quiz Score Distribution
          </h4>
          <VBarChart data={scoreDistribution} emptyLabel="No quiz attempts recorded yet." />
        </div>

        {/* Engagement */}
        <div className="bg-[#131418] border border-[#23252C] rounded-2xl p-5 shadow-sm space-y-4">
          <h4 className="text-xs font-bold text-[#EDEFF5] flex items-center gap-1.5 pb-3 border-b border-[#23252C]">
            <Award size={14} className="text-[#6E79F4]" /> Activity Engagement Rate
          </h4>
          <HBarChart data={engagementChart} emptyLabel="No activities published yet." />
        </div>
      </div>

      {/* Rankings */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-4 sm:gap-6">
        <div className="bg-[#131418] border border-[#23252C] rounded-2xl p-5 shadow-sm space-y-4">
          <h4 className="text-xs font-bold text-[#EDEFF5] flex items-center gap-1.5 pb-3 border-b border-[#23252C]">
            <Trophy size={14} className="text-[#F5B04A]" /> Top Performers
          </h4>
          {topPerformers.length === 0 ? (
            <div className="text-center py-8 border border-dashed border-[#23252C] rounded-xl text-xs text-[#C2C6D1]">No student data yet.</div>
          ) : (
            <div className="space-y-2.5">
              {topPerformers.map((s, i) => (
                <div key={s.id} className="flex items-center justify-between gap-3 p-2.5 rounded-xl bg-[#16171D] border border-[#23252C]">
                  <div className="flex items-center gap-2.5 min-w-0">
                    <span className="w-6 h-6 rounded-full bg-[#F5B04A]/10 text-[#F5B04A] border border-[#F5B04A]/20 flex items-center justify-center font-black text-[10px] shrink-0">
                      {i + 1}
                    </span>
                    <span className="text-xs font-bold text-[#EDEFF5] truncate">{s.name}</span>
                  </div>
                  <span className="text-xs font-black text-[#2FBF71] shrink-0">{s.composite}%</span>
                </div>
              ))}
            </div>
          )}
        </div>

        <div className="bg-[#131418] border border-[#23252C] rounded-2xl p-5 shadow-sm space-y-4">
          <h4 className="text-xs font-bold text-[#EDEFF5] flex items-center gap-1.5 pb-3 border-b border-[#23252C]">
            <AlertTriangle size={14} className="text-[#F0555D]" /> Needs Attention (&lt;70%)
          </h4>
          {needsAttention.length === 0 ? (
            <div className="text-center py-8 border border-dashed border-[#23252C] rounded-xl text-xs text-emerald-600 font-semibold">All students in good standing!</div>
          ) : (
            <div className="space-y-2.5">
              {needsAttention.map((s) => (
                <div key={s.id} className="flex items-center justify-between gap-3 p-2.5 rounded-xl bg-[#F0555D]/5 border border-[#F0555D]/15">
                  <span className="text-xs font-bold text-[#EDEFF5] truncate">{s.name}</span>
                  <span className="text-xs font-black text-[#F0555D] shrink-0">{s.composite}%</span>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

"use client";

import { useInputsChanged, useHydrated } from "@/hooks/use-inputs-changed";
import type { Institution, Enrollment, Program, LessonProgress, Lesson, CohortReport } from "@/types/campus";
import React, { useState, useEffect } from "react";
import {

  Users,
  Search,
  CheckCircle,
  Clock,
  X,
  ExternalLink,
  TrendingUp,
  ChevronDown,
  Loader2
} from "lucide-react";
import { CustomSelect } from "@/components/custom-select";
import { getStudentDeliveryDataAction, listStudentLessonProgressAction } from "@/app/actions/delivery-actions";
import { listLessonsForCourseAction } from "@/app/actions/academic-actions";
import { getAttendanceStatsAction } from "@/app/actions/attendance-actions";

import { useDeliveryData, useLearningData } from "@/hooks/use-delivery";
import { useAcademicPrefetchData } from "@/hooks/use-academics";
import AppShell from "@/components/app-shell";
import { DashboardLoader } from "@/components/dashboard-loader";
import AnalyticsTab from "./analytics-tab";

interface InstitutionPanelProps {
  adminEmail: string;
  institution: Institution;
  tenantId: string;
  primaryRole: string;
}

export default function InstitutionPanel({ 
  adminEmail, 
  institution, 
  tenantId,
  primaryRole
}: InstitutionPanelProps) {
  // Navigation states
  const [activeTab, setActiveTab] = useState<"roster" | "analytics">(() => {
    return "analytics";
  });

  // Hydrate the active tab from the URL after mount. Reading
  // window.location during the initial render causes an SSR/client
  // hydration mismatch, so it must happen in an effect.
  const hydrated = useHydrated();
  if (useInputsChanged([hydrated]) && hydrated) {
    (() => {
    const params = new URLSearchParams(window.location.search);
    const tab = params.get("tab");
    if (tab && ["roster", "analytics"].includes(tab)) {
      setActiveTab(tab as "roster" | "analytics");
    }

  })();
  }

  useEffect(() => {
    if (typeof window !== "undefined") {
      const params = new URLSearchParams(window.location.search);
      if (params.get("tab") !== activeTab) {
        params.set("tab", activeTab);
        const newSearch = params.toString();
        const newUrl = `${window.location.pathname}${newSearch ? "?" + newSearch : ""}`;
        window.history.replaceState(null, "", newUrl);
      }
    }
  }, [activeTab]);

  // React Query Data Fetching
  const { data: deliveryData, isLoading: loadingDelivery, error: deliveryError } = useDeliveryData(tenantId);
  const { data: learningData, isLoading: loadingLearning, error: learningError } = useLearningData(tenantId);
  const { data: academicData, isLoading: loadingAcademic, error: academicError } = useAcademicPrefetchData(tenantId);

  // Default fallbacks during initial hydration
  const initialCohorts = deliveryData?.cohorts || [];
  const enrollments = deliveryData?.enrollments || [];
  const instructors = deliveryData?.instructors || [];
  const activities = learningData?.activities || [];
  const projectSubmissions = learningData?.projectSubmissions || [];
  const challengeSubmissions = learningData?.challengeSubmissions || [];
  const quizAttempts = learningData?.quizAttempts || [];
  const programs = academicData?.programs || [];
  const coursesList = academicData?.courses || [];

  // Roster and Drawer states
  const [selectedCohortId, setSelectedCohortId] = useState<string>("");

  if (useInputsChanged([initialCohorts, selectedCohortId])) {
    (() => {
    if (initialCohorts.length > 0 && !selectedCohortId) {
      setSelectedCohortId(initialCohorts[0].id);
    }
  })();
  }

  const [selectedStudent, setSelectedStudent] = useState<Enrollment | null>(null);
  const [activeStudentProgress, setActiveStudentProgress] = useState<Program[]>([]);
  const [activeStudentLessonsProgress, setActiveStudentLessonsProgress] = useState<LessonProgress[]>([]);
  const [drawerLessonsCache, setDrawerLessonsCache] = useState<Record<string, Lesson[]>>({});
  const [studentDetailTab, setStudentDetailTab] = useState<"overview" | "syllabus" | "quizzes" | "projects" | "challenges">("overview");
  const [rosterSearch, setRosterSearch] = useState("");

  // Collapsible accordion states in drawer
  const [expandedCourseId, setExpandedCourseId] = useState<string | null>(null);
  const [expandedQuizId, setExpandedQuizId] = useState<string | null>(null);
  const [expandedProjectId, setExpandedProjectId] = useState<string | null>(null);

  // Derived datasets
  const cohorts = initialCohorts;
  const currentCohortEnrollments = enrollments.filter(e => e.cohort_id === selectedCohortId);

  const [cohortReports, setCohortReports] = useState<Record<string, CohortReport>>({});
  const [loadingReports, setLoadingReports] = useState(false);

  useEffect(() => {
    const loadReports = async () => {
      setLoadingReports(true);
      const reports: Record<string, CohortReport> = {};
      for (const c of cohorts) {
        try {
          const res = await getAttendanceStatsAction(c.id);
          if (res.stats) {
            reports[c.id] = res.stats;
          }
        } catch (err) {
          console.error("Failed to load report for cohort:", c.id, err);
        }
      }
      setCohortReports(reports);
      setLoadingReports(false);
    };
    if (cohorts.length > 0) {
      loadReports();
    }
  }, [cohorts]);

  const filteredEnrollments = currentCohortEnrollments.filter(enr => {
    const studentName = enr.student?.full_name?.toLowerCase() || "";
    const studentEmail = enr.student?.email?.toLowerCase() || "";
    const search = rosterSearch.toLowerCase();
    return !rosterSearch || studentName.includes(search) || studentEmail.includes(search);
  });

  // Which roster row is currently prefetching its drawer data
  const [openingStudentId, setOpeningStudentId] = useState<string | null>(null);

  // Load ALL of a student's data first, then open the drawer
  const openStudentDrawer = async (enr: Enrollment) => {
    if (openingStudentId) return;
    setOpeningStudentId(enr.id);
    setStudentDetailTab("overview");
    try {
      const [progRes, lessonsRes, syllabusEntries] = await Promise.all([
        getStudentDeliveryDataAction(enr.user_id),
        listStudentLessonProgressAction(enr.user_id),
        // Prefetch every course's lesson list so the syllabus tab is instant
        Promise.all(
          coursesList.map(async (c) => {
            if (drawerLessonsCache[c.id]) return [c.id, drawerLessonsCache[c.id]] as const;
            const res = await listLessonsForCourseAction(c.id);
            return [c.id, res.success && res.lessons ? res.lessons : []] as const;
          })
        ),
      ]);
      setActiveStudentProgress(progRes.success && progRes.programs ? progRes.programs : []);
      setActiveStudentLessonsProgress(lessonsRes.success && lessonsRes.progressList ? lessonsRes.progressList : []);
      setDrawerLessonsCache(prev => ({ ...prev, ...Object.fromEntries(syllabusEntries) }));
      setSelectedStudent(enr);
    } finally {
      setOpeningStudentId(null);
    }
  };

  // Clear cached progress when the drawer closes


  // Lazy load lessons for courses expanded inside the student detail drawer
  useEffect(() => {
    if (expandedCourseId && !drawerLessonsCache[expandedCourseId]) {
      listLessonsForCourseAction(expandedCourseId).then(res => {
        if (res.success && res.lessons) {
          setDrawerLessonsCache(prev => ({ ...prev, [expandedCourseId]: res.lessons }));
        }
      });
    }
  }, [expandedCourseId, drawerLessonsCache]);

  const renderStudentDetailDrawer = () => {
    if (!selectedStudent) return null;

    // Real student progress percentage from enrollment/overall computed average
    const progressPercentage = selectedStudent.progress_percentage || 0;

    // Filter submissions for this student
    const studentProjSubs = projectSubmissions.filter(sub => sub.student_id === selectedStudent.user_id);
    const studentChalSubs = challengeSubmissions.filter(sub => sub.student_id === selectedStudent.user_id);
    const studentQuizAttemptsList = quizAttempts.filter(att => att.student_id === selectedStudent.user_id);

    const quizzes = activities.filter(a => a.activity_type_code === "quiz");
    const projects = activities.filter(a => a.activity_type_code === "project");
    const challenges = activities.filter(a => a.activity_type_code === "programming");

    // Real student quiz attempts mapper
    const studentQuizAttempts = quizzes.map(q => {
      const attempt = studentQuizAttemptsList.find(att => att.activity_id === q.id);
      return {
        id: q.id,
        title: q.title,
        attempted: !!attempt,
        passed: attempt ? (attempt.score >= (q.passing_score || 0)) : false,
        score: attempt ? attempt.score : 0,
        maxScore: q.max_score || 100,
        submittedAt: attempt ? new Date(attempt.created_at || attempt.updated_at).toLocaleDateString() : ""
      };
    });

    // Real syllabus lessons mapper using lazy loaded drawerLessonsCache and activeStudentLessonsProgress
    const studentSyllabus = coursesList.map((course) => {
      const courseLessons = drawerLessonsCache[course.id] || [];
      return {
        id: course.id,
        title: course.title,
        lessons: courseLessons.map(l => {
          const progressEntry = activeStudentLessonsProgress.find(p => p.lesson_id === l.id);
          return {
            id: l.id,
            title: l.title,
            status: progressEntry?.status_code || "not_started"
          };
        })
      };
    });

    return (
      <div className="fixed inset-0 bg-black/40 backdrop-blur-md z-50 flex justify-end animate-fadeIn">
        <div className="absolute inset-0 cursor-pointer" onClick={() => setSelectedStudent(null)} />
        <div className="relative w-full sm:max-w-3xl bg-[#131418] h-full shadow-2xl flex flex-col z-50 animate-slideOver overflow-hidden sm:border-l border-[#23252C]">

          {/* Drawer Header */}
          <div className="p-4 sm:p-6 border-b border-[#23252C] flex justify-between items-start gap-3 bg-[#16171D] shrink-0">
            <div className="flex gap-3 items-center min-w-0">
              <div className="w-10 h-10 sm:w-12 sm:h-12 rounded-2xl bg-[#6E79F4] text-white flex items-center justify-center font-bold text-base sm:text-lg uppercase shadow-md border border-[#6E79F4]/10 shrink-0">
                {(selectedStudent.student?.full_name || selectedStudent.student?.email || "S").substring(0, 2)}
              </div>
              <div className="min-w-0">
                <h3 className="text-sm sm:text-base font-bold text-[#EDEFF5] truncate">{selectedStudent.student?.full_name || "Enrolled Student"}</h3>
                <p className="text-xs text-[#C2C6D1] truncate">{selectedStudent.student?.email}</p>
                <div className="flex items-center gap-2 mt-1 flex-wrap">
                  <span className="px-2 py-0.5 rounded-full text-[9px] font-bold bg-[#6E79F4]/10 text-[#6E79F4] border border-[#6E79F4]/20">
                    {selectedStudent.cohort?.name || "No cohort"}
                  </span>
                  <span className="text-[10px] text-[#C2C6D1]">• Enrolled on {new Date((selectedStudent.created_at ?? "")).toLocaleDateString()}</span>
                </div>
              </div>
            </div>

            <button 
              onClick={() => setSelectedStudent(null)}
              className="p-1.5 hover:bg-[#23252C] rounded-xl transition-all border border-transparent hover:border-[#23252C] cursor-pointer"
            >
              <X size={18} className="text-[#C2C6D1]" />
            </button>
          </div>

          {/* Drawer Tab Navigation */}
          <div className="flex border-b border-[#23252C] px-3 sm:px-6 bg-[#131418] shrink-0 overflow-x-auto no-scrollbar">
            {(["overview", "syllabus", "quizzes", "projects", "challenges"] as const).map(tab => (
              <button
                key={tab}
                onClick={() => setStudentDetailTab(tab)}
                className={`py-3 px-3 sm:px-4 text-xs font-bold border-b-2 transition-all capitalize cursor-pointer shrink-0 whitespace-nowrap ${
                  studentDetailTab === tab 
                    ? "border-[#6E79F4] text-[#6E79F4] font-bold" 
                    : "border-transparent text-[#C2C6D1] hover:text-[#EDEFF5]"
                }`}
              >
                {tab}
              </button>
            ))}
          </div>

          {/* Drawer Body Scroll */}
          <div className="flex-1 overflow-y-auto p-4 sm:p-6 space-y-6">

            {/* 1. OVERVIEW TAB */}
            {studentDetailTab === "overview" && (
              <div className="space-y-6 animate-fadeIn">
                <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
                  <div className="bg-[#6E79F4]/5 border border-[#6E79F4]/10 rounded-2xl p-4 text-center">
                    <span className="text-[10px] font-bold text-[#C2C6D1] uppercase block tracking-wider">Course Progress</span>
                    <div className="text-xl font-black text-[#6E79F4] mt-1">{progressPercentage}%</div>
                    <div className="w-full bg-[#23252C] h-1.5 rounded-full mt-2 overflow-hidden">
                      <div className="bg-[#6E79F4] h-full" style={{ width: `${progressPercentage}%` }}></div>
                    </div>
                  </div>

                  <div className="bg-[#2FBF71]/5 border border-[#2FBF71]/20 rounded-2xl p-4 text-center">
                    <span className="text-[10px] font-bold text-[#C2C6D1] uppercase block tracking-wider">Quizzes Cleared</span>
                    <div className="text-xl font-black text-[#2FBF71] mt-1">
                      {studentQuizAttemptsList.length} / {quizzes.length}
                    </div>
                    <span className="text-[8px] text-[#C2C6D1] block mt-2">
                      Avg Score: {
                        studentQuizAttemptsList.length > 0 
                          ? Math.round(studentQuizAttemptsList.reduce((acc, curr) => acc + (curr.score || 0), 0) / studentQuizAttemptsList.length)
                          : 0
                      }%
                    </span>
                  </div>

                  <div className="bg-[#F5B04A]/5 border border-[#F5B04A]/20 rounded-2xl p-4 text-center">
                    <span className="text-[10px] font-bold text-[#C2C6D1] uppercase block tracking-wider">Projects Submitted</span>
                    <div className="text-xl font-black text-[#F5B04A] mt-1">
                      {studentProjSubs.length} / {projects.length}
                    </div>
                    <span className="text-[8px] text-[#C2C6D1] block mt-2">
                      Approved: {studentProjSubs.filter(p => p.review?.review_status === "approved").length}
                    </span>
                  </div>

                  <div className="bg-[#22D3EE]/5 border border-[#22D3EE]/20 rounded-2xl p-4 text-center">
                    <span className="text-[10px] font-bold text-[#C2C6D1] uppercase block tracking-wider">Coding Runs</span>
                    <div className="text-xl font-black text-[#22D3EE] mt-1">
                      {studentChalSubs.length} / {challenges.length}
                    </div>
                    <span className="text-[8px] text-[#C2C6D1] block mt-2">
                      Accepted: {studentChalSubs.filter(c => c.submission_status_code === "accepted").length}
                    </span>
                  </div>
                </div>

                <div className="bg-[#131418] border border-[#23252C] rounded-2xl p-5 space-y-4 shadow-sm">
                  <h4 className="text-xs font-bold text-[#EDEFF5] flex items-center gap-1.5 pb-3 border-b border-[#23252C]">
                    <TrendingUp size={14} className="text-[#6E79F4]" /> Performance Indicators
                  </h4>
                  <div className="divide-y divide-[#23252C] text-xs">
                    <div className="py-3 flex justify-between">
                      <span className="text-[#C2C6D1] font-medium">Platform Activity Status</span>
                      <span className="font-bold text-[#2FBF71] flex items-center gap-1">
                        <span className="w-1.5 h-1.5 bg-[#2FBF71] rounded-full animate-ping"></span> Active in Cohort
                      </span>
                    </div>
                    <div className="py-3 flex justify-between">
                      <span className="text-[#C2C6D1] font-medium">Completed Syllabus Lessons</span>
                      <span className="font-bold text-[#EDEFF5]">
                        {activeStudentLessonsProgress.filter(p => p.status_code === "completed").length} Core Lessons
                      </span>
                    </div>
                  </div>
                </div>
              </div>
            )}

            {/* 2. SYLLABUS TAB */}
            {studentDetailTab === "syllabus" && (
              <div className="space-y-6 animate-fadeIn">
                {studentSyllabus.length === 0 ? (
                  <div className="text-center py-10 border border-dashed border-[#23252C] rounded-xl text-xs text-[#C2C6D1]">
                    No courses available in this syllabus context.
                  </div>
                ) : (
                  studentSyllabus.map(course => {
                    const isExpanded = expandedCourseId === course.id;
                    return (
                      <div key={course.id} className="bg-[#131418] border border-[#23252C] rounded-2xl shadow-sm overflow-hidden">
                        <div 
                          onClick={() => setExpandedCourseId(isExpanded ? null : course.id)}
                          className="p-5 flex justify-between items-center gap-4 cursor-pointer hover:bg-[#16171D]/80 transition-colors select-none"
                        >
                          <div className="flex items-center gap-2.5">
                            <ChevronDown 
                              className={`w-4 h-4 text-[#C2C6D1] transition-transform duration-200 ${isExpanded ? "transform rotate-180" : ""}`} 
                            />
                            <h4 className="text-xs font-extrabold text-[#EDEFF5]">{course.title}</h4>
                          </div>
                          <span className="text-[10px] font-bold text-[#6E79F4] bg-[#6E79F4]/10 px-2 py-0.5 rounded-full border border-[#6E79F4]/20 shrink-0">Course</span>
                        </div>

                        {isExpanded && (
                          <div className="p-5 border-t border-[#23252C] space-y-2.5 bg-[#16171D]/30">
                            {course.lessons.map(lesson => (
                              <div key={lesson.id} className="flex justify-between items-center text-xs p-2.5 bg-[#131418] border border-[#23252C] rounded-xl hover:bg-[#16171D] transition-all shadow-sm">
                                <div className="flex items-center gap-2.5">
                                  {lesson.status === "completed" ? (
                                    <div className="w-5 h-5 rounded-full bg-emerald-100 text-emerald-600 flex items-center justify-center border border-emerald-200"><CheckCircle className="w-3 h-3" /></div>
                                  ) : lesson.status === "in_progress" ? (
                                    <div className="w-5 h-5 rounded-full bg-amber-100 text-amber-600 flex items-center justify-center border border-amber-200"><Clock className="w-3 h-3" /></div>
                                  ) : (
                                    <div className="w-5 h-5 rounded-full bg-[#1A1C22] text-[#A3A9B6] flex items-center justify-center font-bold text-[10px] border border-[#23252C]">•</div>
                                  )}
                                  <span className="font-semibold text-[#EDEFF5]">{lesson.title}</span>
                                </div>
                                <span className={`text-[9px] font-bold uppercase px-2 py-0.5 rounded-lg shrink-0 ${
                                  lesson.status === "completed" 
                                    ? "bg-emerald-50 text-emerald-600" 
                                    : lesson.status === "in_progress"
                                    ? "bg-amber-50 text-amber-600"
                                    : "bg-[#1A1C22] text-[#C2C6D1]"
                                }`}>
                                  {lesson.status.replace(/_/g, " ")}
                                </span>
                              </div>
                            ))}
                          </div>
                        )}
                      </div>
                    );
                  })
                )}
              </div>
            )}

            {/* 3. QUIZZES TAB */}
            {studentDetailTab === "quizzes" && (
              <div className="space-y-6 animate-fadeIn">
                {quizzes.length === 0 ? (
                  <div className="text-center py-10 border border-dashed border-[#23252C] rounded-xl text-xs text-[#C2C6D1]">
                    No quizzes found on the platform.
                  </div>
                ) : (
                  quizzes.map(quiz => {
                    const attempts = studentQuizAttemptsList.filter(a => a.activity_id === quiz.id);
                    const sortedAttempts = [...attempts].sort((a, b) => new Date(b.submitted_at || b.created_at || b.updated_at || 0).getTime() - new Date(a.submitted_at || a.created_at || a.updated_at || 0).getTime());
                    const passedAttempt = sortedAttempts.find(att => att.score >= (quiz.passing_score || 0));
                    const attempt = passedAttempt || sortedAttempts[0];
                    const isPassed = attempt ? (attempt.score >= (quiz.passing_score || 0)) : false;

                    return (
                      <div key={quiz.id} className="bg-[#131418] border border-[#23252C] rounded-2xl shadow-sm overflow-hidden text-xs">
                        <div className="p-5 flex justify-between items-center gap-4 hover:bg-[#16171D]/80 transition-colors select-none">
                          <div className="flex items-center gap-2.5">
                            <div>
                              <h4 className="text-xs font-bold text-[#EDEFF5]">{quiz.title}</h4>
                              {attempt && (
                                <p className="text-[9px] text-[#C2C6D1] mt-0.5">
                                  {attempts.length > 1 ? `${attempts.length} attempts • ` : ""}
                                  Last attempt on {new Date(attempt.submitted_at || attempt.created_at || attempt.updated_at).toLocaleDateString()}
                                </p>
                              )}
                            </div>
                          </div>

                          <div className="flex items-center gap-3 shrink-0 font-bold">
                            {attempt ? (
                              isPassed ? (
                                <span className="px-2.5 py-1 rounded bg-[#2FBF71]/10 text-[#2FBF71] border border-[#2FBF71]/20 font-bold text-[10px]">
                                  Passed with {attempt.score} marks
                                </span>
                              ) : (
                                <span className="px-2.5 py-1 rounded bg-red-500/10 text-red-500 border border-red-500/20 font-bold text-[10px]">
                                  Failed with {attempt.score} marks
                                </span>
                              )
                            ) : (
                              <span className="px-2 py-0.5 rounded text-[8px] uppercase bg-[#1A1C22] text-[#A3A9B6]">Not Attempted</span>
                            )}
                          </div>
                        </div>
                      </div>
                    );
                  })
                )}
              </div>
            )}

            {/* 4. PROJECTS TAB */}
            {studentDetailTab === "projects" && (
              <div className="space-y-6 animate-fadeIn">
                {studentProjSubs.length === 0 ? (
                  <div className="text-center py-10 border border-dashed border-[#23252C] rounded-xl text-xs text-[#C2C6D1]">
                    No projects submitted yet by this student.
                  </div>
                ) : (
                  studentProjSubs.map(sub => {
                    const isExpanded = expandedProjectId === sub.id;
                    return (
                      <div key={sub.id} className="bg-[#131418] border border-[#23252C] rounded-2xl shadow-sm overflow-hidden text-xs">
                        <div 
                          onClick={() => setExpandedProjectId(isExpanded ? null : sub.id)}
                          className="p-5 flex justify-between items-center gap-4 cursor-pointer hover:bg-[#16171D]/80 transition-colors select-none"
                        >
                          <div className="flex items-center gap-2.5">
                            <ChevronDown 
                              className={`w-4 h-4 text-[#C2C6D1] transition-transform duration-200 ${isExpanded ? "transform rotate-180" : ""}`} 
                            />
                            <div>
                              <h4 className="text-xs font-bold text-[#EDEFF5]">{sub.project_title}</h4>
                              <p className="text-[9px] text-[#C2C6D1] mt-0.5">Submitted on {new Date(sub.submitted_at).toLocaleDateString()}</p>
                            </div>
                          </div>

                          <span className={`px-2.5 py-0.5 rounded-full text-[9px] font-extrabold border uppercase shrink-0 ${
                            sub.review?.review_status === "approved"
                              ? "bg-emerald-50 text-emerald-600 border-emerald-100"
                              : "bg-amber-50 text-amber-600 border-amber-100"
                          }`}>
                            {sub.review?.review_status || "Pending"}
                          </span>
                        </div>

                        {isExpanded && (
                          <div className="p-5 border-t border-[#23252C] space-y-3 bg-[#16171D]/30">
                            <div>
                              <span className="text-[9px] font-bold text-[#C2C6D1] uppercase tracking-wide block mb-1">GitHub Link</span>
                              <a 
                                href={sub.github_url} 
                                target="_blank" 
                                rel="noopener noreferrer"
                                className="text-xs text-[#6E79F4] font-bold break-all hover:underline flex items-center gap-1 w-fit"
                              >
                                {sub.github_url}
                                <ExternalLink size={12} />
                              </a>
                            </div>

                            {sub.submission_notes && (
                              <div>
                                <span className="text-[9px] font-bold text-[#C2C6D1] uppercase tracking-wide block mb-1">Student Notes</span>
                                <p className="p-3 bg-[#131418] border border-[#23252C] rounded-xl text-[#EDEFF5] italic">
                                  &quot;{sub.submission_notes}&quot;
                                </p>
                              </div>
                            )}

                            {sub.review && (
                              <div className="pt-3 border-t border-[#23252C]">
                                <span className="text-[9px] font-bold text-[#C2C6D1] uppercase tracking-wide block mb-2">Grade & Evaluation</span>
                                <div className="p-3 bg-[#6E79F4]/5 border border-[#6E79F4]/10 rounded-xl space-y-2">
                                  <div className="flex justify-between items-center text-[10px]">
                                    <span className="text-[#C2C6D1] font-medium">Score:</span>
                                    <strong className="text-sm font-black text-[#6E79F4]">{sub.review.score} / {sub.max_score} pts</strong>
                                  </div>
                                  {sub.review.feedback && (
                                    <div className="text-[10px] text-[#EDEFF5] mt-1 pt-1.5 border-t border-[#6E79F4]/10">
                                      <strong className="block text-[#C2C6D1] uppercase text-[8px] tracking-wide mb-0.5">Feedback:</strong>
                                      {sub.review.feedback}
                                    </div>
                                  )}
                                </div>
                              </div>
                            )}
                          </div>
                        )}
                      </div>
                    );
                  })
                )}
              </div>
            )}

            {/* 5. CHALLENGES TAB */}
            {studentDetailTab === "challenges" && (
              <div className="space-y-6 animate-fadeIn">
                {studentChalSubs.length === 0 ? (
                  <div className="text-center py-10 border border-dashed border-[#23252C] rounded-xl text-xs text-[#C2C6D1]">
                    No coding challenges submitted by this student.
                  </div>
                ) : (
                  studentChalSubs.map(sub => (
                    <div key={sub.id} className="bg-[#131418] border border-[#23252C] rounded-2xl shadow-sm p-4 space-y-3 text-xs">
                      <div className="flex justify-between items-center">
                        <div>
                          <h4 className="font-bold text-[#EDEFF5]">{sub.challenge_title || "Coding Challenge"}</h4>
                          <p className="text-[9px] text-[#C2C6D1]">Language: {sub.lang} • Run on {new Date(sub.created_at).toLocaleDateString()}</p>
                        </div>
                        <span className={`px-2.5 py-0.5 rounded-full text-[9px] font-bold border ${
                          sub.submission_status_code === "accepted"
                            ? "bg-emerald-50 text-emerald-600 border-emerald-100"
                            : "bg-red-50 text-red-600 border-red-100"
                        }`}>
                          {sub.submission_status_code}
                        </span>
                      </div>

                      {sub.result && (
                        <div className="bg-[#16171D] border border-[#23252C] p-3 rounded-xl space-y-1.5">
                          <div className="flex justify-between">
                            <span className="text-[#C2C6D1]">Points Awarded:</span>
                            <strong className="text-[#6E79F4]">{sub.result.score} pts</strong>
                          </div>
                          <div className="flex justify-between">
                            <span className="text-[#C2C6D1]">Validation Result:</span>
                            <span>{sub.result.message || "Passed"}</span>
                          </div>
                        </div>
                      )}
                    </div>
                  ))
                )}
              </div>
            )}

          </div>

          <div className="p-4 border-t border-[#23252C] bg-[#16171D] flex justify-end shrink-0">
            <button 
              onClick={() => setSelectedStudent(null)}
              className="bg-[#131418] border border-[#23252C] text-[#EDEFF5] hover:bg-[#1A1C22] font-bold text-xs py-2 px-5 rounded-xl transition-all cursor-pointer"
            >
              Close Drawer
            </button>
          </div>
        </div>
      </div>
    );
  };

  const initialError = deliveryError || learningError || academicError;
  if (initialError) {
    return <div role="alert" className="rounded-xl border border-red-200 bg-red-50 p-5 text-sm text-red-800">Unable to load the campus dashboard. {initialError.message}</div>;
  }

  return (
    <>
      <DashboardLoader loading={loadingDelivery || loadingLearning || loadingAcademic} message="Setting up your Campus environment..." />
      <AppShell
        portalLabel="Campus Admin"
        pageTitle={activeTab === "roster" ? "Student Roster & Progress" : "Performance Analytics"}
        items={[
          { id: "analytics", label: "Analytics", icon: TrendingUp },
          { id: "roster", label: "Students", icon: Users },
        ]}
        activeId={activeTab}
        onSelect={(id) => setActiveTab(id as "roster" | "analytics")}
        userName={adminEmail}
        userMeta={institution.name}
      >
      <div className="flex flex-col gap-6 animate-pageIn">

        {/* ROSTER TABLE */}
        {activeTab === "roster" && (
          <div className="bg-[#131418] border border-[#23252C] rounded-xl p-6 shadow-sm space-y-5 animate-fadeIn">
            <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 pb-4 border-b border-[#23252C]">
              <div>
                <h3 className="text-xs font-bold uppercase tracking-wider text-[#C2C6D1]">Student Progress Registry</h3>
                <p className="text-[11px] text-[#C2C6D1] mt-0.5">Monitor, search, and view performance logs of enrolled candidates.</p>
              </div>

              <div className="flex flex-col sm:flex-row items-start sm:items-center gap-2 w-full sm:w-auto min-w-0">
                <span className="text-xs font-bold text-[#C2C6D1] shrink-0">Cohort:</span>
                <CustomSelect
                  options={cohorts}
                  value={selectedCohortId}
                  onChange={setSelectedCohortId}
                  placeholder="Select cohort group"
                  searchable
                  className="w-full sm:w-64"
                />
              </div>
            </div>

            {selectedCohortId ? (
              <>
                {/* Search Bar */}
                <div className="relative max-w-md">
                  <Search size={14} className="absolute left-3 top-2.5 text-[#C2C6D1]" />
                  <input
                    type="text"
                    placeholder="Search students by name or email..."
                    value={rosterSearch}
                    onChange={(e) => setRosterSearch(e.target.value)}
                    className="w-full bg-[#131418] border border-[#23252C] rounded-xl pl-9 pr-3 py-2 text-xs text-[#EDEFF5] focus:outline-none focus:border-[#6E79F4] shadow-xs"
                  />
                </div>

                {filteredEnrollments.length === 0 ? (
                  <div className="text-center py-10 border border-dashed border-[#23252C] rounded-xl text-xs text-[#C2C6D1]">
                    No student enrollments found matching search filters.
                  </div>
                ) : (
                  <div className="border border-[#23252C] rounded-xl overflow-hidden shadow-xs">
                    <div className="overflow-x-auto">
                      <table className="w-full text-left border-collapse text-xs">
                        <thead>
                          <tr className="bg-[#16171D] border-b border-[#23252C] text-[10px] font-bold text-[#C2C6D1] uppercase tracking-wide">
                            <th className="px-4 py-3">Student Name</th>
                            <th className="px-4 py-3">Email Address</th>
                            <th className="px-4 py-3">Syllabus Progress</th>
                            <th className="px-4 py-3">Status</th>
                            <th className="px-4 py-3">Enrolled Date</th>
                          </tr>
                        </thead>
                        <tbody className="divide-y divide-[#23252C]">
                          {filteredEnrollments.map((enr) => {
                            const progVal = enr.progress_percentage || 0;

                            return (
                              <tr 
                                key={enr.id} 
                                onClick={() => openStudentDrawer(enr)}
                                className={`hover:bg-[#16171D]/50 cursor-pointer transition-colors ${openingStudentId === enr.id ? "opacity-70" : ""}`}
                              >
                                <td className="px-4 py-3.5 font-bold text-[#EDEFF5] flex items-center gap-2">
                                  <div className="w-7 h-7 rounded-full bg-[#6E79F4]/10 text-[#6E79F4] flex items-center justify-center font-bold text-[10px] uppercase border border-[#6E79F4]/25 shrink-0">
                                    {openingStudentId === enr.id
                                      ? <Loader2 size={12} className="animate-spin" />
                                      : (enr.student?.full_name || enr.student?.email || "S").substring(0, 2)}
                                  </div>
                                  <span className="hover:text-[#6E79F4] transition-colors">{enr.student?.full_name || "Enrolled Student"}</span>
                                </td>
                                <td className="px-4 py-3.5 text-[#C2C6D1] font-medium">{enr.student?.email}</td>
                                <td className="px-4 py-3.5">
                                  <div className="flex items-center gap-2 w-36">
                                    <div className="flex-1 bg-[#1A1C22] h-1.5 rounded-full overflow-hidden">
                                      <div className="bg-[#6E79F4] h-full" style={{ width: `${progVal}%` }}></div>
                                    </div>
                                    <span className="font-bold shrink-0">{progVal}%</span>
                                  </div>
                                </td>
                                <td className="px-4 py-3.5">
                                  <span className={`px-2 py-0.5 rounded text-[10px] font-bold ${
                                    enr.status_code === "active" 
                                      ? "bg-emerald-50 text-emerald-600 border border-emerald-100" 
                                      : "bg-[#1A1C22] text-[#C2C6D1]"
                                  }`}>
                                    {enr.status_code}
                                  </span>
                                </td>
                                <td className="px-4 py-3.5 text-[#C2C6D1]">
                                  {new Date(enr.created_at).toLocaleDateString()}
                                </td>
                              </tr>
                            );
                          })}
                        </tbody>
                      </table>
                    </div>
                  </div>
                )}
              </>
            ) : (
              <div className="text-center py-12 border border-dashed border-[#23252C] rounded-xl text-xs text-[#C2C6D1]">
                Please select a cohort group from the dropdown menu to inspect candidate roster logs.
              </div>
            )}
          </div>
        )}

        {/* PERFORMANCE ANALYTICS */}
        {activeTab === "analytics" && (
          <AnalyticsTab
            cohorts={cohorts}
            enrollments={enrollments}
            activities={activities}
            quizAttempts={quizAttempts}
            projectSubmissions={projectSubmissions}
            challengeSubmissions={challengeSubmissions}
            cohortReports={cohortReports}
          />
        )}

      </div>

      {/* Roster detail drawer */}
      {renderStudentDetailDrawer()}

      </AppShell>
    </>
  );
}

