            setSelectedCohort(updatedCohort);
            if (selectedCourse) {
              const updatedCourse = updatedCohort.courses?.find((c) => c.id === selectedCourse.id);
              if (updatedCourse) {
                setSelectedCourse(updatedCourse);
              }
            }
          }
