    const previousProgress = lessonProgressMap[lesson.id];

    // Optimistically update progress to completed in local state map
    setLessonProgressMap(prev => ({
      ...prev,
      [lesson.id]: {
        ...prev[lesson.id],
        status_code: "completed",
