        showError(res.error);
      }
    } catch (err) {
      showError(errorMessage(err, "Failed to load challenge details."));
    } finally {
      setLoading(false);
    }
  };

  const handleSubmitChallenge = async () => {
if (!selectedChallengeActivity) return;

    if (!challengeDetails) return;
    if (!editorCode.trim()) {
      showError("Source code cannot be blank.");
