                            </div>
                            <div className="w-full bg-[#F1F5F9] h-2 rounded-full overflow-hidden">
                              <div
                                className={`h-full rounded-full ${pct === 100 ? "bg-[#2FBF71]" : "bg-[#6E79F4]"}`}
