                      </div>
                    )}
                  </div>
                )}

              </div>

            </div>

          </div>
        )}

        {/* TAB 2: ACADEMICS / SYLLABUS VIEWER */}
        {activeTab === "academics" && (
          <div className="space-y-6 w-full max-w-full overflow-hidden">
            {!selectedCohort ? (
              <div className="text-center py-8 text-[#C2C6D1] font-medium bg-[#131418] border border-[#23252C] rounded-xl p-6 shadow-sm">
