                            </div>
                            <span className="px-2 py-0.5 rounded-full text-[9px] font-bold border bg-[#16171D] text-[#C2C6D1] border-[#23252C]">
                              {typeof course.course_type === "string" ? course.course_type : course.course_type?.code}
