                                <span className="text-[#6E79F4]">Q{idx + 1}.</span> {q.question_text}
                                <span className="font-mono text-[9px] text-[#C2C6D1] bg-[#1A1C22] px-1.5 py-0.5 rounded">({q.points} pts)</span>
